@WillyReyno Same issue for us.  @vercel/oidc is ESM-only and breaks Metro.

We resolved it temporary by mocking AI module during bundling, blocking it in the end.


@vercel/oidc is a transitive dependency of @ai-sdk/gateway (via instantsearch).
This config blocks it and mocks it so the app can bundle

```
// Learn more https://docs.expo.io/guides/customizing-metro
const { getDefaultConfig } = require('expo/metro-config');

const config = getDefaultConfig(__dirname);

// Adds support for `mjs` files (for i18n-js)
config.resolver.sourceExts.push('mjs');

// Ensure node_modules are properly resolved
config.resolver.platforms = ['ios', 'android', 'native', 'web'];
config.resolver.unstable_enableSymlinks = false;

// Alias problematic packages to empty mocks (as suggested by package authors)
// @vercel/oidc is an ESM-only package used by @ai-sdk/gateway but not needed in React Native
// Since we're not using the chat component, we can alias it to an empty package
const path = require('path');
const originalResolveRequest = config.resolver.resolveRequest;
config.resolver.resolveRequest = (context, moduleName, platform) => {
  // Alias @vercel/oidc to empty mock (not needed for React Native, only for chat component)
  if (moduleName === '@vercel/oidc') {
    return {
      filePath: path.resolve(__dirname, 'metro-mocks/@vercel/oidc.js'),
      type: 'sourceFile',
    };
  }
  // Use default resolver for everything else
  if (originalResolveRequest) {
    return originalResolveRequest(context, moduleName, platform);
  }
  return context.resolveRequest(context, moduleName, platform);
};

module.exports = config;

```


where metro-mocks/@vercel/oidc.js is:
```
module.exports = {};

```
